declare const u: unique symbol;
type Quantity<U extends string> = number & { readonly [u]: U };

const m  = (n: number): Quantity<'m'>  => n as Quantity<'m'>;
const km = (n: number): Quantity<'km'> => n as Quantity<'km'>;
const s  = (n: number): Quantity<'s'>  => n as Quantity<'s'>;
const toM = (v: Quantity<'km'>): Quantity<'m'> => m(Number(v) * 1000);
const add = <U extends string>(a: Quantity<U>, b: Quantity<U>) => (a + b) as Quantity<U>;
type Per<A extends string, B extends string> = Quantity<`${A}/${B}`>;
const per = <A extends string, B extends string>(a: Quantity<A>, b: Quantity<B>) => (Number(a) / Number(b)) as Per<A, B>;

const speed = per(m(1500), s(60));   // Quantity<'m/s'>
add(km(3), m(500));                  // type error: 'm' is not assignable to 'km'

